-- Triggers and functions on auth.users cannot be expressed in a Drizzle schema
-- and therefore cannot be generated by drizzle-kit. This is a hand-written
-- custom migration as a deliberate exception to the "never write SQL by hand" rule.

create function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = ''
as $$
begin
  insert into public.profiles (id, full_name)
  values (new.id, new.raw_user_meta_data ->> 'full_name');
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();
